"""Week 4 Day 4 checkpoint-and-resume course-code tests."""

import json
import sys
from dataclasses import replace

import pytest

from .tiny_llm_base import (
    AgentCheckpoint,
    AgentError,
    ModelCheckpoint,
    ReceiptStore,
    ToolPolicy,
    Workspace,
    create_checkpoint,
    resume_agent,
    run_to_checkpoint,
)


class FakeCheckpointModel:
    """Scripted model with a tiny, explicit fake KV snapshot."""

    def __init__(self, responses):
        self.responses = tuple(responses)
        self.response_index = 0
        self.restored = None

    @staticmethod
    def _tokens(messages):
        return tuple(len(message["content"]) for message in messages)

    def __call__(self, messages):
        if self.restored is not None:
            assert self._tokens(messages) == self.restored.cached_token_ids
            assert len(messages) == self.restored.conversation_position
            self.restored = None
        response = self.responses[self.response_index]
        self.response_index += 1
        return response

    def save_checkpoint(self, messages):
        tokens = self._tokens(messages)
        return ModelCheckpoint(
            len(messages), self.response_index, tokens, (len(tokens), len(tokens))
        )

    def restore_checkpoint(self, checkpoint):
        self.response_index = checkpoint.response_index
        self.restored = checkpoint


def test_task_1_model_checkpoint_has_one_aligned_fake_cache_snapshot():
    checkpoint = ModelCheckpoint(4, 2, (11, 12, 13), (3, 3))

    assert checkpoint.conversation_position == 4
    assert checkpoint.response_index == 2
    with pytest.raises(AgentError, match="positions"):
        ModelCheckpoint(-1, 0, (), (0,))
    with pytest.raises(AgentError, match="token ids"):
        ModelCheckpoint(1, 0, (-1,), (1,))
    with pytest.raises(AgentError, match="layer offsets"):
        ModelCheckpoint(1, 0, (1,), (0, 1))


def test_task_2_agent_checkpoint_binds_task_messages_and_model_state():
    messages = [
        {"role": "system", "content": "system"},
        {"role": "user", "content": "inspect"},
    ]
    model = ModelCheckpoint(2, 0, (6, 7), (2,))
    checkpoint = create_checkpoint("inspect", messages, model)

    checkpoint.validate()
    messages[-1]["content"] = "changed outside"
    assert checkpoint.messages[-1] == ("user", "inspect")
    with pytest.raises(AgentError, match="conversation"):
        create_checkpoint("inspect", messages, replace(model, conversation_position=3))
    with pytest.raises(AgentError, match="identity"):
        replace(checkpoint, task="different").validate()
    changed_messages = (checkpoint.messages[0], ("user", "respect"))
    assert len(changed_messages[-1][1]) == len(checkpoint.messages[-1][1])
    with pytest.raises(AgentError, match="identity"):
        replace(checkpoint, messages=changed_messages).validate()
    with pytest.raises(AgentError, match="identity"):
        replace(
            checkpoint,
            model=replace(checkpoint.model, response_index=1),
        ).validate()
    with pytest.raises(AgentError, match="identity"):
        replace(
            checkpoint,
            model=replace(checkpoint.model, cached_token_ids=(6, 8)),
        ).validate()
    with pytest.raises(AgentError, match="identity"):
        replace(
            checkpoint,
            model=replace(checkpoint.model, layer_offsets=(2, 2)),
        ).validate()
    with pytest.raises(AgentError, match="messages"):
        replace(checkpoint, messages=(("user",),)).validate()


def test_task_3_checkpoint_is_saved_after_the_complete_tool_observation(tmp_path):
    (tmp_path / "README.md").write_text("hello\n", encoding="utf-8")
    workspace = Workspace(ToolPolicy(tmp_path))
    model = FakeCheckpointModel(['{"tool":"read_file","path":"README.md"}'])

    checkpoint = run_to_checkpoint("inspect", model, workspace)

    assert checkpoint.model.response_index == 1
    assert checkpoint.model.conversation_position == len(checkpoint.messages) == 4
    assert checkpoint.messages[-2] == (
        "assistant",
        '{"tool":"read_file","path":"README.md"}',
    )
    assert checkpoint.messages[-1] == ("user", "Tool result:\nhello\n")


def test_task_4_checkpoint_api_fails_clearly_before_a_boundary(tmp_path):
    workspace = Workspace(ToolPolicy(tmp_path))

    with pytest.raises(ValueError, match="positive integer"):
        run_to_checkpoint("inspect", FakeCheckpointModel(()), workspace, 0)
    with pytest.raises(AgentError, match="ended before checkpoint"):
        run_to_checkpoint(
            "inspect", FakeCheckpointModel(['{"final":"done"}']), workspace
        )
    with pytest.raises(AgentError, match="does not support checkpoints"):
        run_to_checkpoint(
            "inspect",
            lambda _messages: '{"tool":"list_files","path":"."}',
            workspace,
        )


def test_task_5_resume_requires_valid_content_and_a_restorable_model(tmp_path):
    workspace = Workspace(ToolPolicy(tmp_path))
    model = FakeCheckpointModel(['{"tool":"list_files","path":"."}'])
    checkpoint = run_to_checkpoint("inspect", model, workspace)

    with pytest.raises(AgentError, match="identity"):
        resume_agent(replace(checkpoint, checkpoint_id="0" * 64), model, workspace)
    with pytest.raises(AgentError, match="checkpoint restore"):
        resume_agent(checkpoint, lambda _messages: '{"final":"done"}', workspace)


def test_task_6_fresh_model_restores_the_exact_next_response(tmp_path):
    workspace = Workspace(ToolPolicy(tmp_path))
    responses = (
        '{"tool":"list_files","path":"."}',
        '{"final":"resumed after listing"}',
    )
    checkpoint = run_to_checkpoint("inspect", FakeCheckpointModel(responses), workspace)
    fresh_model = FakeCheckpointModel(responses)

    result = resume_agent(checkpoint, fresh_model, workspace)

    assert result.completed
    assert result.final == "resumed after listing"
    assert fresh_model.response_index == 2


def test_task_7_edit_checkpoint_resume_validates_without_replaying_effect(tmp_path):
    source = tmp_path / "app.py"
    source.write_text("answer = 1\n", encoding="utf-8")
    validation = (
        sys.executable,
        "-c",
        "from pathlib import Path; assert Path('app.py').read_text() == 'answer = 2\\n'",
    )
    approvals = []
    receipts = ReceiptStore(tmp_path / "receipts.jsonl")
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True, allowed_commands=(validation,)),
        lambda action: approvals.append(action.tool) or True,
        receipts,
    )
    responses = (
        '{"tool":"read_file","path":"app.py"}',
        '{"tool":"edit_file","path":"app.py","old":"1","new":"2"}',
        json.dumps({"tool": "run_command", "argv": list(validation)}),
        '{"final":"changed and validated app.py"}',
    )

    checkpoint = run_to_checkpoint(
        "fix app.py", FakeCheckpointModel(responses), workspace, after_tool_calls=3
    )
    assert source.read_text(encoding="utf-8") == "answer = 2\n"
    assert approvals == ["edit_file", "run_command"]
    assert receipts.get("call-1").changed_artifacts == ("app.py",)
    assert receipts.get("call-2").changed_artifacts == ()
    assert set(AgentCheckpoint.__dataclass_fields__) == {
        "checkpoint_id",
        "task",
        "messages",
        "model",
    }

    result = resume_agent(checkpoint, FakeCheckpointModel(responses), workspace)

    assert result.completed
    assert result.final == "changed and validated app.py"
    assert approvals == ["edit_file", "run_command"]
    assert source.read_text(encoding="utf-8") == "answer = 2\n"
    assert receipts.get("call-1").tool == "edit_file"
    assert receipts.get("call-2").tool == "run_command"
